-- Update: Kleinanzeigen 3282873847 (Bonn-Endenich, Carl-Justi-Str. 23, WE 039)
-- Nachbewertung 17.08.2026 mit ETV-Protokollen 2021-2025, Teilungserklaerung + Grundrissen (dritte Runde).
-- Match ueber data->>'link'; aktualisiert notizen, updated_at (JSON + Spalte). Wunschpreis bleibt 215.000 EUR.

update public.search_properties
set
  data = jsonb_set(jsonb_set(
    data,
    '{notizen}',
    to_jsonb('Analyse 17.08.2026 (ETV-Protokolle 2021-2025 + TE + Grundrisse geprueft): Kaufen wenn Preis passt - bestaetigt. Zielpreis 210.000-215.000 EUR (inkl. 15-20 TEUR Renovierungs-Capex), Erstgebot ~205.000 EUR, Schmerzgrenze 220.000 EUR. Rechnung unveraendert: App-CF +63 EUR/M bei 239.000 EUR (Faktor 20,3); konservativ (n. uml. 47,84 + Ruecklage/Instandhaltung 63 EUR) neutral ab ~226.500 EUR; abzueglich Capex ~209.000 EUR sauberer Einstand.\nETV-Protokolle (Kern): KEINE einzige Sonderumlage 2021-2025, alle Massnahmen aus Ruecklage/lfd. Instandhaltung. 2025 beschlossen: Aufzugsmodernisierung UG1+2 fuer 212.680 EUR (Schmitt+Sohn, inkl. TUEV-Maengel) AUS DER RUECKLAGE. Balkone: Statiker-Entwarnung 2025 (durchbetoniert, keine offenen Bewehrungen, nur Maler 2027/28). Sockelsanierung ~32.400 EUR beschlossen (Ruecklage). Treppenhausfenster: marode, 1:1-Erneuerung ohne Brandschutz-Auflagen moeglich, Beschluss ETV 2026 erwartet (Ruecklage). 15-Jahres-Instandhaltungsplan seit 2024. Verwalterwechsel moeglich: Beirat holt Vergleichsangebote, Neubestellung zum 01.01.2027 offen.\nDEALBREAKER-KANDIDAT 1 - Asbest-Fassade: Fassadenplatten asbesthaltig, wiederkehrende Undichtigkeiten; Komplettsanierung (Varianten 163-220 TEUR nur PLANUNG, Gesamtmassnahme Millionenbereich) wurde 31.10.2023 mehrheitlich ABGELEHNT - Projekt beendet, seither nur Flickwerk (Platten nachbefestigen, abdichten). Vertagt, nicht geloest: in 10-15 J. kommt die Sanierung doch (WE-39-Anteil bei z. B. 3 Mio grob ~31 TEUR). Langfrist-Risiko, das der Kaufpreis abbilden muss.\nDEALBREAKER-KANDIDAT 2 - Wassereintritt 5. OG Haus 23 (ETV 29.10.2025, TOP 14): Bei Starkregen Wasser in DIE Wohnung im 5. OG von Haus Nr. 23 eingedrungen - das ist entweder WE 39 (Kaufobjekt!) oder WE 40 (rechts). Instandsetzung mit Geruest ~5.000 EUR beschlossen (lfd. Instandhaltung Haus 23). VOR NOTARTERMIN klaeren: Welche Wohnung? Ausgefuehrt + dicht? Folgeschaeden/Schimmel in WE 39?\nVonovia-Stimmmacht beziffert: Verwaltung vertrat in ETV 2025 4.656/10.000 MEA der Vonovia (Einheit 137 = kompletter Block Hs 26-34 mit 3.476 MEA + Rest-Einzelwohnungen) und kippte damit einen Beschluss der Anwesenden (2.349 MEA). Kleineigentuemer ist Passagier; finanziell traegt Vonovia aber auch ~47 % jeder Massnahme.\nTE/GO (28.05.2003 + Ergaenzung 11.07.2003): 6 Instandhaltungskreise (WE 39 in Kreis 1 = Haeuser 19-23, eigene Ruecklage; UG1-Anteil ~434 TEUR), hausweise Kostentrennung. Par. 7.3: FENSTER/Rolllaeden/Tueren inkl. Erneuerung = Pflicht des SONDEREIGENTUEMERS - Wohnungsfenster Original 1974 sind Kaeufer-Capex, nicht WEG! Gaszentralheizung in Haus 19 versorgt alle Kreise, Kosten tragen alle Angeschlossenen (Vonovia ~47 % mit). Par. 6: Verwalterzustimmung bei Wiederverkauf (Kosten traegt Verkaeufer), Erstverkauf ausgenommen. Keller NICHT Sondereigentum, nur Sondernutzungsrecht per Zuordnungsurkunde (K 137-221) - im Paket lag nur die Urkunde zu WE 35 (K 194): Zuordnung fuer WE 39 anfordern! Gewerbenutzung nur mit Verwalterzustimmung.\nGrundriss WE 39 (5. OG links, Haus 23): sauberer 3-Zi-Schnitt (Wohnzimmer, Elternzimmer, Kind I, Kueche, Bad + separates WC, Diele) + Loggia UND Wirtschaftsloggia (= die 2 Balkone) - gut vermietbar an Paare/kleine Familien/WG-2er. Loggien-Seite = Westfassade Richtung Bahntrasse (Laerm bei Besichtigung pruefen). Haus 23 hat 6 OG, 5. OG ist vorletzte Etage.\nHeizung: Waermeerzeuger Bj. 1999, in keinem Protokoll ein Tausch geplant; hydraulischer Abgleich seit 2023 verschleppt (Schaetzung 51 TEUR, +89 TEUR falls alle Ventile). Kessel-Art (Konstant- vs. Niedertemperatur, GEG-30-J.-Frist) weiter OFFEN.\nOffen vor Notartermin: Wassereintritt-Klaerung (welche Wohnung, Status), Kessel-Art, Keller-Zuordnungsurkunde WE 39, Besichtigung (Feuchte-/Laermcheck). Mail an Hrn. Duelz entworfen (Besichtigung + 4 Punkte).\nKontakt: Elmar Duelz (Mittelrhein Immobilien Duelz, i. A. Vonovia SE), info@duelz.de, T 06742 9414875, M 0163 6864447, Objekt-ID 200-039.'::text)),
    '{updated_at}', to_jsonb(to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))),
  updated_at = now()
where data->>'link' = 'https://www.kleinanzeigen.de/s-anzeige/bonn-endenich-kapitalanlage-5-og-mit-3-zkb-mit-balkon-provisionsfrei-/3282873847-196-23694';
